INSERT INTO public.lexicon(word,lemma,pos,definition,example,difficulty,register,source,source_url,native_score,learning_value,content_status)
SELECT word,lemma,pos,definition,example,difficulty,register,source,source_url,native_score,learning_value,content_status FROM v
